describe('Notification Auto-dismiss Feature', () => {
    beforeEach(() => {
        cy.visit('/'); // Adjust the URL to the application under test
    });

    it('should display a notification and auto-dismiss after 5 seconds', () => {
        // Trigger the notification
        cy.get('.notify-button').click(); // Adjust selector to trigger notification

        // Assert that the notification is visible
        cy.get('.notification').should('be.visible');

        // Wait for 5 seconds
        cy.wait(5000);

        // Assert that the notification is no longer visible
        cy.get('.notification').should('not.exist');
    });

    it('should not dismiss the notification if it is manually closed before 5 seconds', () => {
        // Trigger the notification
        cy.get('.notify-button').click(); // Adjust selector to trigger notification

        // Assert that the notification is visible
        cy.get('.notification').should('be.visible');

        // Manually close the notification
        cy.get('.notification .close-button').click(); // Adjust selector for close button

        // Assert that the notification is no longer visible
        cy.get('.notification').should('not.exist');

        // Wait for 5 seconds to ensure it does not reappear
        cy.wait(5000);
        cy.get('.notification').should('not.exist');
    });
});
